function validate([word1, word2]) {
  if (word1.length < 1 || word1.length > 1000) return 'word1 needs 1 to 1000 letters.';
  if (word2.length < 1 || word2.length > 1000) return 'word2 needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Use only lowercase English letters.';
  return null;
}

