function longestPalindrome(word1, word2) {
  const s = word1 + word2;
  const n = s.length;
  const split = word1.length;
  const dp = Array.from({ length: n }, () => new Uint16Array(n));
  let best = 0;

  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        dp[i][j] = dp[i + 1][j - 1] + 2;
        if (i < split && j >= split) {
          best = Math.max(best, dp[i][j]);
        }
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
      }
    }
  }
  return best;
}

brute:
function longestPalindrome(word1, word2) {
  // Fix the outermost pair: word1[a] on the left and word2[b] on the right. Whatever sits between them
  // is any palindromic subsequence of the text between those two characters, found as an LCS with its reverse.
  const lps = (text) => {
    const rev = [...text].reverse().join('');
    let prev = new Array(text.length + 1).fill(0);
    for (let x = 1; x <= text.length; x++) {
      const cur = new Array(text.length + 1).fill(0);
      for (let y = 1; y <= text.length; y++) {
        cur[y] = text[x - 1] === rev[y - 1] ? prev[y - 1] + 1 : Math.max(prev[y], cur[y - 1]);
      }
      prev = cur;
    }
    return prev[text.length];
  };
  let answer = 0;
  for (let a = 0; a < word1.length; a++) {
    for (let b = 0; b < word2.length; b++) {
      if (word1[a] !== word2[b]) continue;
      answer = Math.max(answer, 2 + lps(word1.slice(a + 1) + word2.slice(0, b)));
    }
  }
  return answer;
}

