function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (length, alphabet) => Array.from({ length }, () => letters[Math.floor(rand() * alphabet)]).join('');
  if (size === 'large') {
    const alphabet = [2, 3, 5, 26][Math.floor(rand() * 4)];
    return [word(1000, alphabet), word(1000, alphabet)];
  }
  const alphabet = 1 + Math.floor(rand() * 4);
  return [word(1 + Math.floor(rand() * 7), alphabet), word(1 + Math.floor(rand() * 7), alphabet)];
}
